cat << 'EOF' > a11y_test.js
const { chromium } = require('playwright');
const fs = require('fs');
const path = require('path');

(async () => {
  const browser = await chromium.launch();
  const page = await browser.newPage();

  const filePath = 'file://' + path.resolve('index.html');
  await page.goto(filePath, { waitUntil: 'networkidle' });

  // Wait for React to finish rendering via Babel
  try {
    await page.waitForSelector('.example', { timeout: 15000 });
  } catch (e) {
    console.log("Timeout waiting for .example. React might not have rendered.");
  }

  // Inject axe-core
  const axeSource = fs.readFileSync('/tmp/axe.min.js', 'utf8');
  await page.evaluate(axeSource);

  const results = await page.evaluate(async () => {
    return await window.axe.run();
  });

  await browser.close();

  const wcag = results.violations.filter(v => !v.tags.includes('best-practice'));
  const bp = results.violations.filter(v => v.tags.includes('best-practice'));

  console.log(JSON.stringify({
    wcag: wcag.map(v => ({ id: v.id, impact: v.impact, description: v.description, targets: v.nodes.map(n => n.target) })),
    bp: bp.map(v => ({ id: v.id, targets: v.nodes.map(n => n.target) }))
  }, null, 2));

  process.exit(wcag.length > 0 ? 1 : 0);
})();
EOF

