                </div>
            </noscript>
        </div>
    </div>

    <script type="text/babel">
        const { useState } = React;

        const FAQ_DATA = [
            {
                id: 'purr',
                question: 'Why do cats purr?',
                answer: 'Cats purr for various reasons, including contentment, stress relief, and healing. The frequency of a cat’s purr (25-150 Hertz) has been shown to improve bone density and promote healing of tendons.'
            },
            {
                id: 'whiskers',
                question: 'Why do cats have whiskers?',
                answer: 'Whiskers are highly sensitive tactile hairs that act as a sensory tool. They help cats navigate in the dark, detect changes in air currents, and determine if they can fit through tight spaces.'
            },
            {
                id: 'kneading',
                question: 'Why do cats knead (make biscuits)?',
                answer: 'Kneading is a behavior carried over from kittenhood, where they knead their mothers to stimulate milk flow. In adults, it is often a sign of comfort, a way to mark territory with scent glands in their paws, or to create a soft sleeping spot.'
            },
            {
                id: 'water',
                question: 'Why do cats hate water?',
                answer: 'Many cats dislike water because their fur becomes heavy and slow-drying when wet, making them feel vulnerable. Additionally, some cats may be sensitive to the smell of chemicals in tap water or simply haven’t been exposed to it much.'
            },
            {
                id: 'gifts',
                question: 'Why do cats bring you "gifts" like mice?',
                answer: 'In the wild, mother cats bring dead or injured prey to their kittens to teach them how to eat and hunt. Your cat may be treating you as their family, attempting to share their hunting success or teach you how to "hunt."'
            }
        ];

        function FAQItem({ question, answer, id }) {
            const [isOpen, setIsOpen] = useState(false);

            const toggleOpen = () => setIsOpen(!isOpen);

            return (
                <div className="example">
                    <h2>
                        <button
                            type="button"
                            className="question-trigger"
                            onClick={toggleOpen}
                            aria-expanded={isOpen}
                            aria-controls={`panel-${id}`}
                            id={`btn-${id}`}
                        >
                            {question}
                            <svg className="icon" viewBox="0 0 24 24" aria-hidden="true">
