                            </svg>
                        </button>
                    </h2>
                    <div
                        className="details"
                        id={`panel-${id}`}
                        role="region"
                        aria-labelledby={`btn-${id}`}
                        hidden={!isOpen}
                    >
                        {answer}
                    </div>
                </div>
            );
        }

        function App() {
            return (
                <div className="container">
                    <header>
                        <h1>Cat FAQ</h1>
                    </header>
                    <main>
                        {FAQ_DATA.map((item) => (
                            <FAQItem
                                key={item.id}
                                id={item.id}
                                question={item.question}
                                answer={item.answer}
                            />
                        ))}
                    </main>
                </div>
            );
        }

        const root = ReactDOM.createRoot(document.getElementById('root'));
        root.render(<App />);
    </script>
